 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content"></main>

   <script>
     const notificationChoices = [
       { id: "notify-email", value: "Email", label: "Email" },
       { id: "notify-sms", value: "SMS", label: "SMS" },
       { id: "notify-push", value: "Push Notifications", label: "Push Notifications" }
     ];

     function PageShell(children) {
       return `
         <div class="page-shell">
           <section class="card" aria-labelledby="page-title">
             <p class="eyebrow">Preference Center</p>
             <h1 id="page-title">Choose your notification preference</h1>
             <p class="lead">Select exactly one option for how you prefer to receive notifications.</p>
             ${children}
           </section>
         </div>
       `;
     }

     function RadioOption(option) {
       return `
         <div class="radio-option">
           <input
             id="${option.id}"
             type="radio"
             name="notificationPreference"
             value="${option.value}"
             required
           >
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     function NotificationPreferenceField() {
       return `
         <div class="form-field">
           <fieldset class="radio-group" aria-describedby="notification-help notification-error">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-mark" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="field-help">Required. Pick one answer before submitting.</p>
             <div class="radio-options">
               ${notificationChoices.map(RadioOption).join("")}
             </div>
             <p id="notification-error" class="field-error" hidden>Error: Select how you prefer to receive notifications.</p>
           </fieldset>
         </div>
       `;
     }

     function FormSection() {
       return `
         <section class="form-section" aria-labelledby="form-heading">
           <h2 id="form-heading">Notification settings form</h2>
           <form id="preference-form" novalidate>
             ${NotificationPreferenceField()}
             <div class="submit-row">
               <button class="submit-button" type="submit">Save preference</button>
               <p id="form-status" class="status-message" aria-live="polite"></p>
             </div>
           </form>
         </section>
       `;
     }

     function App() {
       return PageShell(FormSection());
     }

     function setGroupInvalidState(isInvalid) {
       const radios = document.querySelectorAll('input[name="notificationPreference"]');
       radios.forEach((radio) => {
         if (isInvalid) {
           radio.setAttribute("aria-invalid", "true");
         } else {
           radio.removeAttribute("aria-invalid");
         }
       });
     }

     function renderApp() {
       document.getElementById("main-content").innerHTML = App();

       const form = document.getElementById("preference-form");
       const status = document.getElementById("form-status");
       const error = document.getElementById("notification-error");
       const radios = document.querySelectorAll('input[name="notificationPreference"]');

       function clearError() {
         error.hidden = true;
         setGroupInvalidState(false);
       }

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           clearError();
           status.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const selected = document.querySelector('input[name="notificationPreference"]:checked');

         if (!selected) {
           error.hidden = false;
           status.textContent = "";
           setGroupInvalidState(true);
           radios[0].focus();
           return;
         }

         clearError();
         status.textContent = `Saved preference: ${selected.value}.`;
       });
     }

     renderApp();
   </script>
 </body>
 </html>

